"""scanPosLast candidate emitter (docs/37).

scalar: optimized C loop coverage slice.
neon: per-CG vector load/saturate/scan-order TBL, then scalar pack of
nonzero/sign masks (vector 16-wide work + compact scalar PEXT).
"""


def emit(func_name="dynopt_scan_pos_last_sve2"):
    return """\
// Generated by tools/emit_scan_pos_last_sve2_shared.py -- do not edit.
#include <stdint.h>
#include <stddef.h>

extern "C" int %s(const uint16_t* scan, const int16_t* coeff,
                  uint16_t* coeffSign, uint16_t* coeffFlag,
                  uint8_t* coeffNum, int numSig,
                  const uint16_t* scanCG4x4, int trSize)
{
    (void)scanCG4x4;  // 4x4 slice: scan table already gives full order
    (void)trSize;
    int scanPosLast = 0;
    uint16_t cSign = 0;
    uint16_t cFlag = 0;
    uint8_t cNum = 0;
    uint32_t prevcgIdx = 0;
    do
    {
        const uint32_t cgIdx = (uint32_t)scanPosLast >> 4;
        const uint32_t posLast = scan[scanPosLast];
        const int curCoeff = coeff[posLast];
        const uint32_t isNZCoeff = (curCoeff != 0);
        numSig -= (int)isNZCoeff;
        if (scanPosLast %% 16 == 0)
        {
            coeffSign[prevcgIdx] = cSign;
            coeffFlag[prevcgIdx] = cFlag;
            coeffNum[prevcgIdx] = cNum;
            cSign = 0;
            cFlag = 0;
            cNum = 0;
        }
        cSign += (uint16_t)(((curCoeff < 0) ? 1 : 0) << cNum);
        cFlag = (uint16_t)((cFlag << 1) + isNZCoeff);
        cNum += (uint8_t)isNZCoeff;
        prevcgIdx = cgIdx;
        scanPosLast++;
    }
    while (numSig > 0);
    coeffSign[prevcgIdx] = cSign;
    coeffFlag[prevcgIdx] = cFlag;
    coeffNum[prevcgIdx] = cNum;
    return scanPosLast - 1;
}
""" % func_name


def emit_combo(combo):
    """NEON layout search dispatcher (--isa neon).

    Axes (all optional):
      mask  pack | dot | addp   -- 16 byte-mask lanes -> two 16-bit masks
                                   (pack: bit loop; dot: four u8 dot
                                   products; addp: 3-step vpaddq chain,
                                   both masks in one dependency chain)
      pext  ctz | clz           -- sign-mask compaction PEXT:
                                   ctz: __builtin_ctz loop (GCC unrolls);
                                   clz: compact clz/lsl/extr/bfc asm loop
      flag  tail                 -- coeffFlag convention: intermediate
                                    CGs store rev16(nz) (bit i = scan
                                    position 15-i); the final CG stores
                                    rev16(nz) >> (15-lastIndex) (bit i =
                                    position lastIndex-i). The tail
                                    strategy stores rev16(nz) in the
                                    loop and fixes only the final CG
                                    once after the loop, mirroring the
                                    upstream NEON asm tail (branch/csel
                                    variants were dropped in round-0021:
                                    they implement the single-CG L=15
                                    special case only and corrupt the
                                    bitstream on real multi-CG TUs).
      count popcount | addv     -- nonzero count from nz popcount or from
                                   the zero-compare vector via vaddvq_u8
    """
    compute = combo.get("compute")
    if compute == "scalar":
        return emit()
    return emit_neon(
        func_name="dynopt_scan_pos_last_sve2",
        mask=combo.get("mask", "dot" if compute == "neon-dot" else "pack"),
        pext=combo.get("pext", "ctz"),
        flag=combo.get("flag", "branch"),
        count=combo.get("count", "popcount"))


def emit_neon(func_name="dynopt_scan_pos_last_sve2", mask="pack",
              pext="ctz", flag="branch", count="popcount"):
    if mask not in ("pack", "dot", "addp"):
        raise ValueError("unknown mask %r" % mask)
    if pext not in ("ctz", "clz", "nibble"):
        raise ValueError("unknown pext %r" % pext)
    if flag != "tail":
        raise ValueError("unknown flag %r" % flag)
    if count not in ("popcount", "addv"):
        raise ValueError("unknown count %r" % count)

    if mask == "pack":
        mask_src = """\
static inline uint16_t pack16(uint8x16_t m)
{
    const uint64_t lo = vgetq_lane_u64(vreinterpretq_u64_u8(m), 0);
    const uint64_t hi = vgetq_lane_u64(vreinterpretq_u64_u8(m), 1);
    uint16_t bits = 0;
    for (int i = 0; i < 8; i++)
    {
        bits |= (uint16_t)(((lo >> (8 * i)) & 1) << i);
        bits |= (uint16_t)(((hi >> (8 * i)) & 1) << (8 + i));
    }
    return bits;
}
"""
        mask_expr = (
            "const uint16_t nz = pack16(vmvnq_u8(zero));\n"
            "        const uint16_t sn = pack16(neg);")
    elif mask == "dot":
        mask_src = """\
static inline uint16_t mask16(uint8x16_t m)
{
    const uint8x16_t one = vdupq_n_u8(1);
    static const uint8_t W[16] =
        { 1, 2, 4, 8, 1, 2, 4, 8, 1, 2, 4, 8, 1, 2, 4, 8 };
    const uint8x16_t w = vld1q_u8(W);
    const uint8x16_t b = vandq_u8(m, one);
    const uint32x4_t s = vdotq_u32(vdupq_n_u32(0), b, w);
    return (uint16_t)(vgetq_lane_u32(s, 0) |
                      (vgetq_lane_u32(s, 1) << 4) |
                      (vgetq_lane_u32(s, 2) << 8) |
                      (vgetq_lane_u32(s, 3) << 12));
}
"""
        mask_expr = (
            "const uint16_t nz = mask16(vmvnq_u8(zero));\n"
            "        const uint16_t sn = mask16(neg);")
    else:  # addp
        mask_src = """\
static inline uint32_t masks_addp(uint8x16_t zero, uint8x16_t neg)
{
    static const uint8_t W[16] =
        { 1, 2, 4, 8, 16, 32, 64, 128, 1, 2, 4, 8, 16, 32, 64, 128 };
    const uint8x16_t w = vld1q_u8(W);
    const uint8x16_t s = vandq_u8(neg, w);
    const uint8x16_t m = vbicq_u8(w, zero);
    uint8x16_t p = vpaddq_u8(s, m);
    p = vpaddq_u8(p, p);
    p = vpaddq_u8(p, p);
    return vgetq_lane_u32(vreinterpretq_u32_u8(p), 0);
}
"""
        mask_expr = (
            "const uint32_t spl = masks_addp(zero, neg);\n"
            "        const uint16_t nz = (uint16_t)(spl >> 16);\n"
            "        const uint16_t sn = (uint16_t)spl;")

    if pext == "nibble":
        # 4-bit table PEXT: AGO M3 template is the single source of
        # truth (optimizer/ago/templates/pext_table.py); the tables are
        # generated from the reference bit-select semantics and carry an
        # exhaustive 65536-case proof obligation (scripts/verify-ago-pext.sh).
        import os
        import sys
        sys.path.insert(0, os.path.join(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
            "optimizer"))
        from ago.templates.pext_table import emit_pext_nibble
        pext_src = emit_pext_nibble()
        pext_call = "pext_nibble(sn, nz, &cnt)"
        count_src = "uint8_t cnt;"
    elif pext == "ctz":
        pext_src = """\
static inline uint16_t pext16(uint16_t val, uint16_t mask)
{
    uint16_t out = 0;
    int bit = 0;
    while (mask)
    {
        const int b = __builtin_ctz((unsigned)mask);
        out |= (uint16_t)(((val >> b) & 1) << bit);
        mask &= (uint16_t)(mask - 1);
        bit++;
    }
    return out;
}
"""
        pext_call = "pext16(sn, nz)"
    else:  # clz
        pext_src = """\
static inline uint16_t pext_clz(uint16_t val, uint16_t mask)
{
    uint32_t v = (uint32_t)val & mask;
    uint32_t m = mask;
    uint32_t out = 0;
    while (m)
    {
        uint32_t sh;
        __asm__ volatile("clz %w[sh], %w[m]"
                         : [sh] "=r"(sh) : [m] "r"(m));
        v <<= sh;
        m <<= sh;
        __asm__ volatile("extr %w[o], %w[o], %w[v], #31\\n\\t"
                         "bfc %w[m], #31, #1"
                         : [o] "+r"(out), [m] "+r"(m)
                         : [v] "r"(v));
    }
    return (uint16_t)out;
}
"""
        pext_call = "pext_clz(sn, nz)"

    if pext == "nibble":
        pass  # count comes from the pext tables above
    elif count == "popcount":
        count_src = ("const uint8_t cnt = "
                     "(uint8_t)__builtin_popcount((unsigned)nz);")
    else:  # addv: zero-compare lanes are 0xFF, so the byte sum is
        # 255*z mod 256 == -z as a signed byte; 16 + (-z) = nonzero count.
        count_src = "const uint8_t cnt = cnt_addv(zero);"

    # tail: store rev16 for every CG; fix the final CG once after the
    # loop (mirrors upstream's rbit-trick placement so the flag work
    # overlaps the scalar PEXT instead of serializing after it).
    flag_src = ("const uint32_t rb = rbit32("
                "(uint32_t)sn | ((uint32_t)nz << 16));\n"
                "        *pf++ = (uint16_t)rb;\n"
                "        rb_last = rb;")
    tail_fix_src = (
        "    if (pn != pn0)\n"
        "    {\n"
        "        const uint32_t w = rbit32(rb_last);\n"
        "        const uint32_t k = __builtin_clz(w);\n"
        "        pf[-1] = (uint16_t)(rb_last >> k);\n"
        "        lastIndex = (int)(15 - (int)k);\n"
        "    }\n")
    last_nz_src = ""

    return """\
// Generated by tools/emit_scan_pos_last_sve2_shared.py -- do not edit.
#include <arm_neon.h>
#include <stdint.h>
#include <stddef.h>

static inline uint16_t rev16(uint16_t x)
{
    // rbit reverses all 32 bits; the reversed low half lands in bits
    // 31..16, so one shift gives the 16-bit reversal without any
    // preloaded constants (the old bit-twiddle version forced GCC to
    // keep six constants live across the whole kernel).
    uint32_t r;
    __asm__("rbit %%w[r], %%w[x]" : [r] "=r"(r) : [x] "r"((uint32_t)x));
    return (uint16_t)(r >> 16);
}

static inline uint32_t rbit32(uint32_t x)
{
    uint32_t r;
    __asm__("rbit %%w[r], %%w[x]" : [r] "=r"(r) : [x] "r"(x));
    return r;
}

static inline uint16_t next_scan_off(const uint16_t** sp)
{
    // Post-increment scan offset load: keeps the per-CG address bump in
    // the load itself (upstream-style) instead of a separate ADD at the
    // loop back-edge.
    uint16_t off;
    __asm__("ldrh %%w[o], [%%[p]], #32"
            : [o] "=r"(off), [p] "+r"(*sp));
    return off;
}

static inline uint8_t cnt_addv(uint8x16_t zero)
{
    // ADDV leaves the byte sum in a vector register; SMOV moves it to a
    // GPR with sign extension. The zero lanes are 0xFF, so the byte sum
    // is -z (mod 256) as a signed byte and 16 + z gives the nonzero
    // count without a separate mask+AND.
    uint8_t s;
    int8_t z;
    __asm__("addv %%b[s], %%[v].16b" : [s] "=w"(s) : [v] "w"(zero));
    __asm__("smov %%w[z], %%[s].b[0]" : [z] "=r"(z) : [s] "w"(s));
    return (uint8_t)(16 + z);
}

%s
%s
extern "C" int %s(const uint16_t* scan, const int16_t* coeff,
                  uint16_t* coeffSign, uint16_t* coeffFlag,
                  uint8_t* coeffNum, int numSig,
                  const uint16_t* scanCG4x4, int trSize)
{
    const uint8x16_t st = vcombine_u8(
        vmovn_u16(vld1q_u16(scanCG4x4)),
        vmovn_u16(vld1q_u16(scanCG4x4 + 8)));
    const int8x16_t zero8 = vdupq_n_s8(0);
    const uint16_t* sc = scan;
    uint16_t* ps = coeffSign;
    uint16_t* pf = coeffFlag;
    uint8_t* pn0 = coeffNum;
    uint8_t* pn = coeffNum;
    int lastIndex = 0;
    uint32_t rb_last = 0;
    while (numSig > 0)
    {
        const uint16_t off = next_scan_off(&sc);
        const int16_t* p = coeff + off;
        const int16x4_t r0 = vld1_s16(p);
        p += trSize;
        const int16x4_t r1 = vld1_s16(p);
        p += trSize;
        const int16x4_t r2 = vld1_s16(p);
        p += trSize;
        const int16x4_t r3 = vld1_s16(p);
        int8x16_t b = vcombine_s8(
            vqmovn_s16(vcombine_s16(r0, r1)),
            vqmovn_s16(vcombine_s16(r2, r3)));
        b = vqtbl1q_s8(b, st);
        const uint8x16_t zero = vceqq_s8(b, zero8);
        const uint8x16_t neg = vcltq_s8(b, zero8);
        %s
        %s
        %s
        const uint16_t sig = %s;
        %s
        *ps++ = sig;
        *pn++ = cnt;
        numSig -= (int)cnt;
    }
    %s
    return (int)((pn - pn0) - 1) * 16 + lastIndex;
}
""" % (mask_src, pext_src, func_name, mask_expr, count_src, flag_src,
       pext_call, last_nz_src, tail_fix_src)
